def atoms(omega, events):
    """The atoms of the sigma-algebra generated by events: a set of frozensets partitioning omega."""
    groups = {}
    for w in omega:
        pattern = tuple(w in e for e in events)
        groups.setdefault(pattern, set()).add(w)
    return {frozenset(g) for g in groups.values()}

def count_events(omega, events):
    """How many events the generated sigma-algebra holds."""
    return 2 ** len(atoms(omega, events))
